import type { ColDef } from 'ag-grid-community';
import { ColumnDefsConfig } from 'components/Table/Table';
import {
  TableCellType,
  TableDataType,
  TableHeaderType,
} from 'components/Table/types';

import { collectLeafColumnIds } from './adjustSubHeaderColSpansForVisibleColumns';

export const GROUP_LABEL_MIN_WIDTHS: Record<string, number> = {
  Volume: 80,
  'Marketing Package': 160,
  NWM: 56,
  Media: 56,
  'Sponsorship & Activation': 160,
  'Campaign Performance': 140,
};

export const SUB_HEADER_LABEL_MIN_WIDTHS: Record<string, number> = {
  'Investment [Mio USD]': 160,
  'QWOA [#]': 80,
  QWOA: 56,
  '% MKT': 72,
  'M/P ratio [#]': 96,
  'k hl': 56,
  '%': 48,
};

const getColumnMinWidth = (
  columnId: string,
  columnDefsConfig: ColumnDefsConfig,
): number => {
  const config = columnDefsConfig[columnId] as ColDef | undefined;
  return typeof config?.minWidth === 'number' ? config.minWidth : 72;
};

const getSubHeaderRow = (
  rows: TableDataType['rows'],
): Record<string, unknown> | undefined => {
  const subHeaderRow = rows?.[0]?.[0];

  if (!subHeaderRow || 'isEmpty' in subHeaderRow) {
    return undefined;
  }

  return subHeaderRow as Record<string, unknown>;
};

const getMergeSpan = (cell: TableCellType): number =>
  cell.colSpan ?? cell.mergeCol ?? 0;

const getSubHeaderLabelWidth = (cell: TableCellType): number => {
  const value = cell.value == null ? '' : String(cell.value);

  return SUB_HEADER_LABEL_MIN_WIDTHS[value] ?? 0;
};

const getCollapsedSubHeaderLabelWidth = (
  subHeaderRow: Record<string, unknown> | undefined,
  columnId: string,
): number => {
  if (!subHeaderRow) {
    return 0;
  }

  const cell = subHeaderRow[columnId];

  if (!cell || typeof cell !== 'object' || Array.isArray(cell)) {
    return 0;
  }

  const tableCell = cell as TableCellType;

  // Merged labels span multiple columns — width is enforced in applyMergeSpanMinWidths.
  if (getMergeSpan(tableCell) > 1) {
    return 0;
  }

  return getSubHeaderLabelWidth(tableCell);
};

const PORTFOLIO_COLUMN_ID = 'portfolio';

const withFixedWidth = (
  header: TableHeaderType,
  width: number,
): TableHeaderType => ({
  ...header,
  minWidth: width,
  maxWidth: width,
  width,
});

const withExpandedWidth = (
  header: TableHeaderType,
  minWidth: number,
  width: number,
): TableHeaderType => ({
  ...header,
  minWidth,
  width,
  maxWidth: undefined,
});

const getLeafMinWidth = (header: TableHeaderType): number =>
  header.minWidth ?? header.width ?? 72;

const getLeafWidth = (header: TableHeaderType): number =>
  header.width ?? header.minWidth ?? 72;

/** Split the group label floor across visible leaves so header group width === sum(children). */
export const getVisibleLeafWidths = (
  children: TableHeaderType[],
  groupTitle: string,
  columnDefsConfig: ColumnDefsConfig,
): number[] => {
  const configWidths = children.map((child) =>
    getColumnMinWidth(child.id!, columnDefsConfig),
  );
  const childrenSum = configWidths.reduce((total, width) => total + width, 0);
  const labelMinWidth = GROUP_LABEL_MIN_WIDTHS[groupTitle] ?? 0;

  if (childrenSum >= labelMinWidth) {
    return configWidths;
  }

  const targetGroupWidth = labelMinWidth;
  const count = children.length;

  if (count === 0) {
    return [];
  }

  const baseWidth = Math.floor(targetGroupWidth / count);
  const remainder = targetGroupWidth % count;

  return configWidths.map((configWidth, index) => {
    const share = baseWidth + (index < remainder ? 1 : 0);
    return Math.max(configWidth, share);
  });
};

const applyLeafWidth = (
  header: TableHeaderType,
  columnDefsConfig: ColumnDefsConfig,
  subHeaderRow: Record<string, unknown> | undefined,
  groupTitle: string,
  isSingleVisibleChild: boolean,
  fixedWidth?: number,
): TableHeaderType => {
  if (!header.id) {
    return header;
  }

  const configMinWidth = getColumnMinWidth(header.id, columnDefsConfig);
  const subHeaderLabelWidth = getCollapsedSubHeaderLabelWidth(
    subHeaderRow,
    header.id,
  );

  if (isSingleVisibleChild) {
    const groupLabelWidth = GROUP_LABEL_MIN_WIDTHS[groupTitle] ?? 0;
    const width = Math.max(
      configMinWidth,
      subHeaderLabelWidth,
      groupLabelWidth,
    );

    return withFixedWidth(header, width);
  }

  return withFixedWidth(
    header,
    Math.max(fixedWidth ?? configMinWidth, subHeaderLabelWidth),
  );
};

const applyToHeaders = (
  headers: TableHeaderType[],
  columnDefsConfig: ColumnDefsConfig,
  subHeaderRow: Record<string, unknown> | undefined,
): TableHeaderType[] =>
  headers.map((header) => {
    if (!header.children?.length) {
      if (!header.id) {
        return header;
      }

      return {
        ...header,
        minWidth: getColumnMinWidth(header.id, columnDefsConfig),
      };
    }

    const leafChildren = header.children.filter((child) => child.id);
    const isSingleVisibleChild = leafChildren.length === 1;
    const distributedWidths = isSingleVisibleChild
      ? []
      : getVisibleLeafWidths(leafChildren, header.title, columnDefsConfig);

    let leafIndex = 0;
    const children = header.children.map((child) => {
      if (!child.id) {
        return child;
      }

      const sizedChild = applyLeafWidth(
        child,
        columnDefsConfig,
        subHeaderRow,
        header.title,
        isSingleVisibleChild,
        distributedWidths[leafIndex],
      );
      leafIndex += 1;

      return sizedChild;
    });

    if (isSingleVisibleChild) {
      const onlyChild = children.find((child) => child.id)!;
      const width =
        onlyChild.width ??
        onlyChild.minWidth ??
        getColumnMinWidth(onlyChild.id!, columnDefsConfig);

      return {
        ...header,
        children,
        ...withFixedWidth({ title: header.title }, width),
      };
    }

    const groupWidth = children.reduce(
      (total, child) => total + (child.width ?? child.minWidth ?? 0),
      0,
    );

    return {
      ...header,
      children,
      minWidth: groupWidth,
    };
  });

const collectLeafMinWidthMap = (
  headers: TableHeaderType[],
  map = new Map<string, number>(),
): Map<string, number> => {
  headers.forEach((header) => {
    if (header.children?.length) {
      collectLeafMinWidthMap(header.children, map);
    } else if (header.id) {
      map.set(header.id, getLeafMinWidth(header));
    }
  });

  return map;
};

const collectLeafWidthMap = (
  headers: TableHeaderType[],
  map = new Map<string, number>(),
): Map<string, number> => {
  headers.forEach((header) => {
    if (header.children?.length) {
      collectLeafWidthMap(header.children, map);
    } else if (header.id) {
      map.set(header.id, getLeafWidth(header));
    }
  });

  return map;
};

const applyWidthMapToLeaves = (
  headers: TableHeaderType[],
  widthById: Map<string, number>,
): TableHeaderType[] =>
  headers.map((header) => {
    if (header.children?.length) {
      const children = applyWidthMapToLeaves(header.children, widthById);
      const groupWidth = children.reduce(
        (total, child) => total + getLeafWidth(child),
        0,
      );

      return {
        ...header,
        children,
        minWidth: groupWidth,
      };
    }

    if (header.id && widthById.has(header.id)) {
      return withFixedWidth(header, widthById.get(header.id)!);
    }

    return header;
  });

/** Ensure merged blue sub-header labels have enough combined column width. */
const applyMergeSpanMinWidths = (
  headers: TableHeaderType[],
  leafIds: string[],
  subHeaderRow: Record<string, unknown> | undefined,
): TableHeaderType[] => {
  if (!subHeaderRow) {
    return headers;
  }

  const widthById = collectLeafWidthMap(headers);

  leafIds.forEach((columnId) => {
    const cell = subHeaderRow[columnId];

    if (!cell || typeof cell !== 'object' || Array.isArray(cell)) {
      return;
    }

    const tableCell = cell as TableCellType;
    const span = getMergeSpan(tableCell);

    if (span <= 1) {
      return;
    }

    const labelWidth = getSubHeaderLabelWidth(tableCell);

    if (labelWidth <= 0) {
      return;
    }

    const anchorIndex = leafIds.indexOf(columnId);

    if (anchorIndex === -1) {
      return;
    }

    const memberIds = leafIds.slice(anchorIndex, anchorIndex + span);
    const currentSum = memberIds.reduce(
      (total, memberId) => total + (widthById.get(memberId) ?? 72),
      0,
    );

    if (currentSum >= labelWidth) {
      return;
    }

    const targetWidthPerMember = Math.ceil(labelWidth / memberIds.length);

    memberIds.forEach((memberId) => {
      widthById.set(
        memberId,
        Math.max(widthById.get(memberId) ?? 72, targetWidthPerMember),
      );
    });
  });

  return applyWidthMapToLeaves(headers, widthById);
};

export const getTotalVisibleMinWidth = (headers: TableHeaderType[]): number => {
  const minWidthById = collectLeafMinWidthMap(headers);

  return [...minWidthById.values()].reduce((total, width) => total + width, 0);
};

/** Split leftover container width evenly across visible columns (never below min width). */
export const distributeContainerWidth = (
  headers: TableHeaderType[],
  leafIds: string[],
  containerWidth?: number,
): TableHeaderType[] => {
  if (!containerWidth || containerWidth <= 0) {
    return headers;
  }

  const minWidthById = collectLeafMinWidthMap(headers);
  const portfolioWidth = minWidthById.get(PORTFOLIO_COLUMN_ID) ?? 0;
  const expandableIds = leafIds.filter((id) => id !== PORTFOLIO_COLUMN_ID);
  const availableWidth = containerWidth - portfolioWidth;

  const totalMinWidth = expandableIds.reduce(
    (total, columnId) => total + (minWidthById.get(columnId) ?? 72),
    0,
  );

  if (totalMinWidth >= availableWidth) {
    return headers;
  }

  const extraWidth = availableWidth - totalMinWidth;
  const extraBase = Math.floor(extraWidth / expandableIds.length);
  const extraRemainder = extraWidth % expandableIds.length;
  const widthById = new Map(minWidthById);

  expandableIds.forEach((columnId, index) => {
    const minWidth = minWidthById.get(columnId) ?? 72;
    const bonus = extraBase + (index < extraRemainder ? 1 : 0);

    widthById.set(columnId, minWidth + bonus);
  });

  return applyExpandedWidthMapToLeaves(headers, widthById, minWidthById);
};

const applyExpandedWidthMapToLeaves = (
  headers: TableHeaderType[],
  widthById: Map<string, number>,
  minWidthById: Map<string, number>,
): TableHeaderType[] =>
  headers.map((header) => {
    if (header.children?.length) {
      const children = applyExpandedWidthMapToLeaves(
        header.children,
        widthById,
        minWidthById,
      );
      const groupWidth = children.reduce(
        (total, child) => total + getLeafWidth(child),
        0,
      );

      return {
        ...header,
        children,
        minWidth: groupWidth,
      };
    }

    if (!header.id || !widthById.has(header.id)) {
      return header;
    }

    const width = widthById.get(header.id)!;
    const minWidth = minWidthById.get(header.id) ?? width;

    if (header.id === PORTFOLIO_COLUMN_ID || width <= minWidth) {
      return withFixedWidth(header, width);
    }

    return withExpandedWidth(header, minWidth, width);
  });

export const applyGroupHeaderMinWidths = (
  data: TableDataType,
  columnDefsConfig: ColumnDefsConfig,
  containerWidth?: number,
): TableDataType => {
  const subHeaderRow = getSubHeaderRow(data.rows);
  const leafIds = collectLeafColumnIds(data.header);
  const sizedHeaders = applyToHeaders(
    data.header,
    columnDefsConfig,
    subHeaderRow,
  );
  const mergedHeaders = applyMergeSpanMinWidths(
    sizedHeaders,
    leafIds,
    subHeaderRow,
  );

  return {
    ...data,
    header: distributeContainerWidth(mergedHeaders, leafIds, containerWidth),
  };
};
